import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const availableModels = [
  'model.obj',
  'model2.obj',
  // Add more models here
];

const loadModel = (modelPath) => {
  return new Promise((resolve, reject) => {
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => resolve(obj),
      undefined,
      (error) => reject(error)
    );
  });
};

const ModelLoader = ({ modelPath, modelCache }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);

  useEffect(() => {
    // If model is in cache, use it
    if (modelCache[modelPath]) {
      setModel(modelCache[modelPath]);
      return;
    }

    // Otherwise, load the model
    loadModel(modelPath)
      .then((loadedModel) => {
        setModel(loadedModel);
        modelCache[modelPath] = loadedModel; // Cache the model
      })
      .catch((error) => console.error('Error loading model:', error));
  }, [modelPath, modelCache]);

  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [selectedModel, setSelectedModel] = useState(availableModels[0]);
  const [highlightedModel, setHighlightedModel] = useState(null);

  // Cache loaded models to avoid reloading
  const modelCache = useRef({});

  const handleKeyPress = (event) => {
    const currentIndex = availableModels.indexOf(selectedModel);
    if (event.key === 'ArrowDown') {
      const nextIndex = (currentIndex + 1) % availableModels.length;
      setSelectedModel(availableModels[nextIndex]);
    } else if (event.key === 'ArrowUp') {
      const prevIndex = (currentIndex - 1 + availableModels.length) % availableModels.length;
      setSelectedModel(availableModels[prevIndex]);
    }
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [selectedModel]);

  const handleModelClick = (model) => {
    setSelectedModel(model);
  };

  return (
    <div style={{ display: 'flex' }}>
      {/* Left Sidebar */}
      <div
        style={{
          width: '200px',
          height: '100vh',
          backgroundColor: '#333',
          padding: '20px',
          color: 'white',
          overflowY: 'auto',
        }}
      >
        <h3>Select a Model</h3>
        <ul style={{ listStyle: 'none', paddingLeft: 0 }}>
          {availableModels.map((model, index) => (
            <li
              key={model}
              style={{
                padding: '10px',
                cursor: 'pointer',
                backgroundColor: selectedModel === model ? '#555' : '',
                color: selectedModel === model ? 'yellow' : 'white',
                fontWeight: highlightedModel === model ? 'bold' : 'normal',
              }}
              onClick={() => handleModelClick(model)}
              onMouseEnter={() => setHighlightedModel(model)}
              onMouseLeave={() => setHighlightedModel(null)}
            >
              {model}
            </li>
          ))}
        </ul>
      </div>

      {/* 3D Canvas */}
      <div style={{ flex: 1, height: '100vh' }}>
        <Canvas
          style={{ backgroundColor: 'black' }}
          camera={{
            position: [2.5, 2.5, 2.5],
            fov: 45,
          }}
        >
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} intensity={1} />
          <directionalLight position={[5, 5, 5]} intensity={1} />
          {/* Load model from the public folder */}
          <ModelLoader modelPath={`./stls/${selectedModel}`} modelCache={modelCache.current} />
          <OrbitControls
            enableZoom={false}
            minPolarAngle={Math.PI / 4}
            maxPolarAngle={Math.PI / 4}
            minAzimuthAngle={-Math.PI / 4}
            maxAzimuthAngle={Math.PI / 4}
          />
        </Canvas>
      </div>
    </div>
  );
};

export default App;
